import{_ as l,C as i,o as e,c as n,a2 as t,b as s,w as o,a as E,E as A,a3 as C}from"./chunks/framework.BBdhqAg0.js";const B="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"워크스페이스 관리 (Workspace Master)","description":"","frontmatter":{},"headers":[],"relativePath":"work-setting/ws-manage.md","filePath":"work-setting/ws-manage.md","lastUpdated":1793195756000}'),c={name:"work-setting/ws-manage.md"};function d(h,a,u,g,m,p){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="워크스페이스-관리-workspace-master" tabindex="-1">워크스페이스 관리 (Workspace Master) <a class="header-anchor" href="#워크스페이스-관리-workspace-master" aria-label="Permalink to &quot;워크스페이스 관리 (Workspace Master)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+B+'" alt="워크스페이스 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/ws-manage.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>워크스페이스 관리</strong> 페이지는 시스템 관리자가 회사 내 모든 협업 공간(본사 관리, 부동산 개발 프로젝트, 기타 공간)의 계층 구조와 생애주기를 전사적 관점에서 총괄 제어하는 마스터 관리 대시보드입니다.</p></blockquote><h2 id="_1-개요-및-관리자-허브" tabindex="-1">1. 개요 및 관리자 허브 <a class="header-anchor" href="#_1-개요-및-관리자-허브" aria-label="Permalink to &quot;1. 개요 및 관리자 허브&quot;">​</a></h2><p>개별 워크스페이스 내부의 <a href="/work-manage/settings.html">설정</a> 메뉴가 특정 협업 공간의 세부 옵션을 다룬다면, <strong>워크스페이스 관리</strong>는 전사 레벨에서 운영 중인 모든 워크스페이스를 한눈에 파악하고 신규 개설, 복제, 잠금보관(아카이빙), 안전 삭제를 일괄 처리하는 중앙 통제 센터입니다.</p><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[설정 관리] → [워크스페이스 관리]**를 선택하여 접속합니다. (관리자 권한 필요)</li></ul>',6)),(e(),s(C,null,{default:o(()=>[A(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20%EC%83%9D%EC%95%A0%EC%A3%BC%EA%B8%B0%EC%A0%9C%EC%96%B4%20%5B%22%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%83%9D%EC%95%A0%EC%A3%BC%EA%B8%B0%20%EA%B4%80%EB%A6%AC%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%E2%9E%95%20%EC%83%88%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EA%B0%9C%EC%84%A4%3Cbr%3E(%EA%B8%B0%EB%B3%B8%20%EC%83%9D%EC%84%B1%20%EB%98%90%EB%8A%94%20%EA%B8%B0%EC%A1%B4%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EB%B3%B5%EC%A0%9C)%22%5D%20--%3E%20B%5B%22%F0%9F%9F%A2%20%EC%A0%95%EC%83%81%20%EC%9A%B4%EC%98%81%20(Active)%3Cbr%3E(%EB%AA%A8%EB%93%88%20%EC%97%B0%EB%8F%99%20%26%20%EA%B3%84%EC%B8%B5%ED%98%95%20%ED%8A%B8%EB%A6%AC)%22%5D%0A%20%20%20%20%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%9F%A1%20%EC%9E%A0%EA%B8%88%EB%B3%B4%EA%B4%80%20(Archive)%3Cbr%3E(%EC%9D%BC%EB%B0%98%20%EC%A0%91%EA%B7%BC%20%EC%B0%A8%EB%8B%A8%20%2F%20%EC%9D%B4%EB%A0%A5%20%EB%B3%B4%EC%A1%B4)%22%5D%0A%20%20%20%20%20%20%20%20B%20%26%20C%20--%3E%20D%5B%22%F0%9F%97%91%EF%B8%8F%20%EC%95%88%EC%A0%84%20%EC%82%AD%EC%A0%9C%3Cbr%3E(%EC%8B%9D%EB%B3%84%EC%9E%90%20%ED%99%95%EC%9D%B8%20%2F%20%EC%9D%B4%EB%A0%A5%20%EC%9E%88%EC%9D%84%20%EC%8B%9C%20%EC%9E%A0%EA%B8%88%EB%B3%B4%EA%B4%80%20%EC%9E%90%EB%8F%99%20%EC%A0%84%ED%99%98)%22%5D%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="_2-워크스페이스-목록-그리드-및-시각화" tabindex="-1">2. 워크스페이스 목록 그리드 및 시각화 <a class="header-anchor" href="#_2-워크스페이스-목록-그리드-및-시각화" aria-label="Permalink to &quot;2. 워크스페이스 목록 그리드 및 시각화&quot;">​</a></h2><p>전체 워크스페이스를 트리 계층과 상태 배지로 직관적으로 표현하여 조직 전체의 협업 공간 현황을 조망할 수 있습니다.</p><h3 id="🌲-계층형-트리-구조-depth-indentation" tabindex="-1">🌲 계층형 트리 구조 (Depth Indentation) <a class="header-anchor" href="#🌲-계층형-트리-구조-depth-indentation" aria-label="Permalink to &quot;🌲 계층형 트리 구조 (Depth Indentation)&quot;">​</a></h3><ul><li>상위 워크스페이스와 하위 워크스페이스의 종속 관계가 화살표(<code>&gt;</code>)와 들여쓰기로 시각화되어 본사-사업지 간의 지배구조 및 프로젝트 하위 그룹을 한눈에 파악하기 쉽습니다.</li></ul><h3 id="🏷️-상태-및-식별-배지" tabindex="-1">🏷️ 상태 및 식별 배지 <a class="header-anchor" href="#🏷️-상태-및-식별-배지" aria-label="Permalink to &quot;🏷️ 상태 및 식별 배지&quot;">​</a></h3><ul><li><strong>내 워크스페이스 (초록색 배지)</strong>: 로그인한 사용자가 현재 구성원으로 참여 중인 공간을 표시합니다.</li><li><strong>비공개 워크스페이스 (자물쇠 아이콘)</strong>: 초대된 멤버만 접근 가능한 보안 공간입니다.</li><li><strong>북마크 (별/북마크 배지)</strong>: 사용자가 즐겨찾기로 등록해 둔 주요 워크스페이스입니다.</li><li><strong>잠금/닫힘 상태</strong>: 이미 마감되었거나 잠금보관된 워크스페이스는 전체 행이 회색 텍스트로 감쇄되어 현재 활성화된 운영 공간과 명확히 구분됩니다.</li></ul><h3 id="📋-컬럼-커스터마이징-column-selector" tabindex="-1">📋 컬럼 커스터마이징 (Column Selector) <a class="header-anchor" href="#📋-컬럼-커스터마이징-column-selector" aria-label="Permalink to &quot;📋 컬럼 커스터마이징 (Column Selector)&quot;">​</a></h3><p>우측 상단의 컬럼 선택기 버튼을 통해 그리드에 표출할 항목을 자유롭게 지정할 수 있으며, 설정값은 브라우저에 영구 저장됩니다:</p><ul><li><strong>제공 컬럼</strong>: 이름(기본 고정), 식별자(<code>Slug</code>), 설명, 상태, 홈페이지, 상위 워크스페이스, 공개 여부, 등록일, 수정일</li></ul><h3 id="🔍-잠금보관-항목-포함-검색" tabindex="-1">🔍 잠금보관 항목 포함 검색 <a class="header-anchor" href="#🔍-잠금보관-항목-포함-검색" aria-label="Permalink to &quot;🔍 잠금보관 항목 포함 검색&quot;">​</a></h3><ul><li>기본적으로 정상 운영 중인 활성 워크스페이스만 조회됩니다.</li><li>과거 종료되었거나 보관 처리된 프로젝트를 확인하려면 검색 옵션의 <strong>&#39;잠금보관 포함&#39;</strong> 체크박스를 활성화하여 검색할 수 있습니다.</li></ul><h2 id="_3-워크스페이스-생애주기-제어-actions" tabindex="-1">3. 워크스페이스 생애주기 제어 (Actions) <a class="header-anchor" href="#_3-워크스페이스-생애주기-제어-actions" aria-label="Permalink to &quot;3. 워크스페이스 생애주기 제어 (Actions)&quot;">​</a></h2><p>각 워크스페이스 행 우측의 더보기(<code>...</code>) 메뉴를 통해 다음과 같은 생애주기 제어 작업을 수행할 수 있습니다. (관리자 권한 필요)</p><h3 id="➕-새-워크스페이스-생성-및-복사-copy" tabindex="-1">➕ 새 워크스페이스 생성 및 복사 (Copy) <a class="header-anchor" href="#➕-새-워크스페이스-생성-및-복사-copy" aria-label="Permalink to &quot;➕ 새 워크스페이스 생성 및 복사 (Copy)&quot;">​</a></h3><ul><li><strong>새 워크스페이스</strong>: 완전히 새로운 프로젝트나 협업 부서를 위한 공간을 개설합니다. 명칭, 식별자(영문 URL 키), 설명, 공개 여부 및 활성화할 기능 모듈을 설정합니다.</li><li><strong>워크스페이스 복사</strong>: 기존 워크스페이스의 활성화된 기능 모듈, 업무 트래커, 범주, 기본 설정을 그대로 복제합니다. 유사한 신규 사업지나 새 프로젝트 공간을 만들 때 매우 유용합니다.</li></ul><h3 id="🔒-잠금보관-archive-잠금보관-해제" tabindex="-1">🔒 잠금보관 (Archive) / 잠금보관 해제 <a class="header-anchor" href="#🔒-잠금보관-archive-잠금보관-해제" aria-label="Permalink to &quot;🔒 잠금보관 (Archive) / 잠금보관 해제&quot;">​</a></h3><ul><li><strong>잠금보관</strong>: 사업이 종료되었거나 일시 중단된 워크스페이스를 &#39;잠금보관&#39; 상태로 전환합니다. <ul><li>일반 구성원의 신규 접근 및 데이터 수정이 전면 차단됩니다.</li><li>과거의 업무, 회의록, 문서, 결재 이력은 유실 없이 안전하게 영구 보존됩니다.</li></ul></li><li><strong>보관 해제</strong>: 재개된 프로젝트나 추가 확인이 필요한 경우, 원클릭으로 잠금보관을 해제하여 즉시 정상 운영 상태로 복원할 수 있습니다.</li></ul><h3 id="🗑️-2단계-안전-삭제-및-데이터-보호-정책" tabindex="-1">🗑️ 2단계 안전 삭제 및 데이터 보호 정책 <a class="header-anchor" href="#🗑️-2단계-안전-삭제-및-데이터-보호-정책" aria-label="Permalink to &quot;🗑️ 2단계 안전 삭제 및 데이터 보호 정책&quot;">​</a></h3><ul><li><strong>식별자 검증</strong>: 실수로 인한 데이터 삭제 사고를 원천 방지하기 위해, 삭제 팝업창에 해당 워크스페이스의 <strong>고유 식별자(Slug)를 정확히 타이핑해야만 [삭제] 버튼이 활성화</strong>됩니다.</li><li><strong>⭐️ 데이터 자동 보호 정책 (중요)</strong>: <ul><li>업무(Issue), 회의(Meeting), 문서(Document) 등 단 1건이라도 활동 이력이 존재하는 워크스페이스는 물리적으로 완전 삭제되지 않고, <strong>시스템이 자동으로 &#39;잠금보관&#39; 상태로 안전하게 전환</strong>하여 회사의 소중한 데이터 자산 유실을 방지합니다.</li></ul></li></ul><h2 id="_4-실무-운영-가이드" tabindex="-1">4. 실무 운영 가이드 <a class="header-anchor" href="#_4-실무-운영-가이드" aria-label="Permalink to &quot;4. 실무 운영 가이드&quot;">​</a></h2><ul><li><strong>표준 템플릿 워크스페이스 활용</strong>: 표준 업무 프로세스(트래커, 범주, 기본 마일스톤)가 사전 세팅된 &#39;표준 템플릿&#39; 워크스페이스를 개설해 두고, 새 사업지 런칭 시 <strong>[복사]</strong> 기능을 이용하면 단 1분 만에 일관된 협업 환경을 구축할 수 있습니다.</li><li><strong>정기적인 아카이빙(보관) 관리</strong>: 분양이 완료되었거나 정산이 끝난 프로젝트는 즉시 &#39;잠금보관&#39; 처리하여 활성 목록을 슬림하게 유지하십시오. 과거 데이터가 필요할 때는 언제든지 &#39;잠금보관 포함&#39; 검색으로 손쉽게 열람할 수 있습니다.</li></ul>',21))])}const D=l(c,[["render",d]]);export{b as __pageData,D as default};
